mapper.update:
update tb_task
set group_name = #{groupName}
where group_id = #{groupId}

mapper.select:
select ta.id, ta.ics_msg_id, ta.user_id, ta.post_id, ta.group_id, ta.group_name, ta.seqid, ta.text, ta.from_user_id, ta.from_user_name, ta.from_user_nick, ta.from_user_department_id, ta.from_user_department_name, ta.msg_sent_time, ta.msg_file_id, ta.status, ta.is_deleted, ta.gmt_modified, ta.gmt_created, ta.reply from tb_task ta
and ta.status =#{qo.type}
and ta.user_id =#{qo.userId}
and ta.text like concat('%',#{keywords},'%')
and ta.id is not null
order by ta.gmt_modified desc

select count(1) from tb_task

    post_id in (select id from tb_collaboration_post)

        and user_id = #{userId}


        and post_id = #{postId}


        and user_id IN

            #{id}



        and status IN

            #{status}



        and gmt_modified >= #{startTime}


        and gmt_modified <= CONCAT(#{endTime}, ' 23:59:59')

SELECT tt.id, tt.ics_msg_id, tt.user_id, tt.post_id, tt.group_id, tt.group_name, tt.seqid, tt.text, tt.from_user_id, tt.from_user_name, tt.from_user_nick, tt.from_user_department_id, tt.from_user_department_name, tt.msg_sent_time, tt.msg_file_id, tt.status, tt.is_deleted, tt.gmt_modified, tt.gmt_created, tt.reply FROM tb_task tt LEFT JOIN tb_collaboration_post tcp ON tt.post_id = tcp.id WHERE tcp.deleted = 0
and tt.user_id = #{userId}
and tt.post_id IN
#{postId}
and tt.user_id IN
#{id}
and tt.status IN
#{status}
and tt.gmt_modified >= #{startTime}
and tt.gmt_modified <= CONCAT(#{endTime}, ' 23:59:59')

SELECT cp.org_code AS departmentCode, cp.org_name AS departmentName, AVG(TIMESTAMPDIFF(SECOND, tb_task.gmt_created, tb_task.gmt_modified)) AS avgReplyDuration FROM tb_task join tb_collaboration_post cp on tb_task.post_id = cp.id
tb_task.is_deleted = 0 and tb_task.reply = 1
and cp.org_id IN
#{code}
and cp.id IN
#{id}
and tb_task.gmt_modified >= CONCAT(#{startTime}, ' 00:00:00')
and tb_task.gmt_modified <= CONCAT(#{endTime}, ' 23:59:59')
GROUP BY cp.org_code , cp.org_name ORDER BY avgReplyDuration ASC LIMIT 10;

SELECT cp.org_code AS departmentCode, cp.org_name AS departmentName, COUNT(CASE WHEN reply = 1 THEN 1 END) AS total FROM tb_task left join( SELECT DISTINCT task_id, department_id, department_name, post_id FROM tb_task_response ) tr on tb_task.id=tr.task_id left join tb_collaboration_post cp on tr.post_id=cp.id
tb_task.is_deleted = 0 and tb_task.reply = 1
and tr.department_id IN
#{code}
and tr.post_id IN
#{id}
and tb_task.gmt_modified >= #{startTime}
and tb_task.gmt_modified <= CONCAT(#{endTime}, ' 23:59:59')
GROUP BY cp.org_code , cp.org_name ORDER BY total DESC LIMIT 10;

SELECT post_id AS postId, COUNT(1) AS cnt FROM tb_task ct
ct.post_id IN
#{collaborationId}
and ct.gmt_modified >= #{startTime}
and ct.gmt_modified <= CONCAT(#{endTime}, ' 23:59:59')
GROUP BY post_id
